import { z } from 'zod';

// Client request to generate a quiz
export const QuizGenerateRequestSchema = z.object({
  documentId: z.string().min(1, 'documentId is required'),
  topic: z.string().min(2, 'Topic must be at least 2 characters').max(100),
  numberOfQuestions: z.coerce.number().int().min(1).max(20).default(5),
  difficulty: z.enum(['easy', 'medium', 'hard']).default('medium').optional(),
});

// Single MCQ Question schema generated by LLM / Dify Workflow
export const QuizQuestionItemSchema = z.object({
  question: z.string().min(5, 'Question text is too short'),
  options: z.array(z.string().min(1, 'Option cannot be empty')).length(4, 'Must have exactly 4 options'),
  correctAnswer: z.number().int().min(0).max(3, 'correctAnswer must be index 0, 1, 2, or 3'),
  explanation: z.string().min(5, 'Explanation must be provided and grounded in context'),
});

// Entire Structured output from Dify Workflow
export const QuizWorkflowOutputSchema = z.object({
  title: z.string().min(2).default('Assessment Quiz'),
  questions: z.array(QuizQuestionItemSchema).min(1, 'At least 1 question is required'),
});

// Client submission for grading
export const QuizSubmissionRequestSchema = z.object({
  quizId: z.string().min(1, 'quizId is required'),
  answers: z.record(z.string(), z.number().int().min(0).max(3)),
});

export type QuizGenerateRequestInput = z.infer<typeof QuizGenerateRequestSchema>;
export type QuizQuestionItem = z.infer<typeof QuizQuestionItemSchema>;
export type QuizWorkflowOutput = z.infer<typeof QuizWorkflowOutputSchema>;
export type QuizSubmissionRequestInput = z.infer<typeof QuizSubmissionRequestSchema>;

/**
 * Robust JSON extraction helper: LLMs sometimes wrap JSON in markdown code blocks:
 * ```json { ... } ```
 * This helper cleans and parses the payload safely.
 */
export function extractAndParseJson<T>(rawText: string, schema: z.ZodSchema<T>): T {
  let cleaned = rawText.trim();
  
  // Strip markdown code fences if present
  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  }
  
  // Try to find the outermost JSON object { ... }
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    cleaned = cleaned.substring(firstBrace, lastBrace + 1);
  }

  const parsed = JSON.parse(cleaned);
  return schema.parse(parsed);
}
